mapper.sql:
WHERE cp.deleted = 0
AND ( cp.title LIKE CONCAT('%', #{keyword}, '%') OR cp.summary LIKE CONCAT('%', #{keyword}, '%') OR cp.slug LIKE CONCAT('%', #{keyword}, '%') )
AND cp.publish_status = #{publishStatus}

mapper.update:
UPDATE content_post
SET publish_status = #{toStatus},
    published_time = CASE WHEN #{toStatus} = 1 THEN NOW() ELSE published_time END
WHERE id = #{id}
  AND deleted = 0
  AND publish_status = #{fromStatus}
